using Microsoft.VisualStudio.TestTools.UnitTesting;
using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    // ── Stock level basics ──────────────────────────────────────────

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN"));
    }

    [TestMethod]
    public void AddStock_SingleAdd_IncreasesLevel()
    {
        _tracker.AddStock("SKU-1", 10);
        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void AddStock_MultipleAdds_Accumulates()
    {
        _tracker.AddStock("SKU-1", 5);
        _tracker.AddStock("SKU-1", 3);
        Assert.AreEqual(8, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void AddStock_DifferentSkus_TrackedIndependently()
    {
        _tracker.AddStock("A", 4);
        _tracker.AddStock("B", 7);
        Assert.AreEqual(4, _tracker.GetStockLevel("A"));
        Assert.AreEqual(7, _tracker.GetStockLevel("B"));
    }

    // ── AddStock validation ─────────────────────────────────────────

    [TestMethod]
    public void AddStock_ZeroQuantity_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-1", 0));
    }

    [TestMethod]
    public void AddStock_NegativeQuantity_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-1", -5));
    }

    [TestMethod]
    public void AddStock_NullSku_Throws()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.AddStock(null!, 1));
    }

    [TestMethod]
    public void AddStock_EmptySku_Throws()
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.AddStock("", 1));
    }

    // ── RemoveStock ─────────────────────────────────────────────────

    [TestMethod]
    public void RemoveStock_ReducesLevel()
    {
        _tracker.AddStock("SKU-1", 10);
        _tracker.RemoveStock("SKU-1", 4);
        Assert.AreEqual(6, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void RemoveStock_EntireStock_LeavesZero()
    {
        _tracker.AddStock("SKU-1", 5);
        _tracker.RemoveStock("SKU-1", 5);
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void RemoveStock_MoreThanAvailable_Throws()
    {
        _tracker.AddStock("SKU-1", 3);
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-1", 4));
    }

    [TestMethod]
    public void RemoveStock_NoStock_Throws()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-1", 1));
    }

    [TestMethod]
    public void RemoveStock_ZeroQuantity_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.RemoveStock("SKU-1", 0));
    }

    // ── Reorder alerts ──────────────────────────────────────────────

    [TestMethod]
    public void NeedsReorder_NoThresholdNoStock_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.SetReorderThreshold("SKU-1", 5);
        _tracker.AddStock("SKU-1", 10);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
    {
        _tracker.SetReorderThreshold("SKU-1", 5);
        _tracker.AddStock("SKU-1", 5);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.SetReorderThreshold("SKU-1", 10);
        _tracker.AddStock("SKU-1", 3);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockOneAboveThreshold_ReturnsFalse()
    {
        _tracker.SetReorderThreshold("SKU-1", 5);
        _tracker.AddStock("SKU-1", 6);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void SetReorderThreshold_UpdatesExisting()
    {
        _tracker.SetReorderThreshold("SKU-1", 5);
        _tracker.SetReorderThreshold("SKU-1", 20);
        Assert.AreEqual(20, _tracker.GetReorderThreshold("SKU-1"));
    }

    [TestMethod]
    public void SetReorderThreshold_Negative_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.SetReorderThreshold("SKU-1", -1));
    }

    // ── Warehouse-specific stock ────────────────────────────────────

    [TestMethod]
    public void AddStock_SpecificWarehouse_TrackedSeparately()
    {
        _tracker.AddStock("SKU-1", 5, "East");
        _tracker.AddStock("SKU-1", 3, "West");
        Assert.AreEqual(5, _tracker.GetStockLevel("SKU-1", "East"));
        Assert.AreEqual(3, _tracker.GetStockLevel("SKU-1", "West"));
    }

    [TestMethod]
    public void GetTotalStockLevel_SumsAllWarehouses()
    {
        _tracker.AddStock("SKU-1", 5, "East");
        _tracker.AddStock("SKU-1", 3, "West");
        _tracker.AddStock("SKU-1", 2, "Central");
        Assert.AreEqual(10, _tracker.GetTotalStockLevel("SKU-1"));
    }

    [TestMethod]
    public void GetTotalStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetTotalStockLevel("UNKNOWN"));
    }

    // ── Warehouse transfers ─────────────────────────────────────────

    [TestMethod]
    public void TransferStock_MovesUnitsCorrectly()
    {
        _tracker.AddStock("SKU-1", 10, "East");
        _tracker.TransferStock("SKU-1", 4, "East", "West");
        Assert.AreEqual(6, _tracker.GetStockLevel("SKU-1", "East"));
        Assert.AreEqual(4, _tracker.GetStockLevel("SKU-1", "West"));
    }

    [TestMethod]
    public void TransferStock_TotalStockUnchanged()
    {
        _tracker.AddStock("SKU-1", 10, "East");
        _tracker.TransferStock("SKU-1", 4, "East", "West");
        Assert.AreEqual(10, _tracker.GetTotalStockLevel("SKU-1"));
    }

    [TestMethod]
    public void TransferStock_InsufficientSource_Throws()
    {
        _tracker.AddStock("SKU-1", 2, "East");
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferStock("SKU-1", 5, "East", "West"));
    }

    [TestMethod]
    public void TransferStock_SameWarehouse_Throws()
    {
        _tracker.AddStock("SKU-1", 10, "East");
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.TransferStock("SKU-1", 5, "East", "East"));
    }

    [TestMethod]
    public void TransferStock_ZeroQuantity_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.TransferStock("SKU-1", 0, "East", "West"));
    }

    [TestMethod]
    public void TransferStock_EntireStock_EmptiesSource()
    {
        _tracker.AddStock("SKU-1", 7, "East");
        _tracker.TransferStock("SKU-1", 7, "East", "West");
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-1", "East"));
        Assert.AreEqual(7, _tracker.GetStockLevel("SKU-1", "West"));
    }

    // ── NeedsReorder with multiple warehouses ───────────────────────

    [TestMethod]
    public void NeedsReorder_ConsidersTotalAcrossWarehouses()
    {
        _tracker.SetReorderThreshold("SKU-1", 10);
        _tracker.AddStock("SKU-1", 6, "East");
        _tracker.AddStock("SKU-1", 6, "West");
        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_AfterRemoval_ReflectsNewTotal()
    {
        _tracker.SetReorderThreshold("SKU-1", 10);
        _tracker.AddStock("SKU-1", 15, "East");
        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));

        _tracker.RemoveStock("SKU-1", 6, "East");
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }
}

